import collections

class CircularBuffer:
    def __init__(self, capacity):
        self.capacity = capacity
        self.buffer = collections.deque(maxlen=capacity)

    def add(self, item):
        self.buffer.append(item)

    def remove(self, index):
        return self.buffer.popleft()

    def delete(self):
        self.buffer = None
