from Crypto.Hash import HMAC
from Crypto.Util.Padding import pad

def select_defense():
    defense1 = ""Twofish""
    defense2 = ""Blowfish""
    defense3 = ""HMAC-SHA256""

    defense_list = [defense1, defense2, defense3]

    selected_defense = random.choice(defense_list)

    if selected_defense == defense1:
        return Twofish.new(b'thisisthetwofishkey', mode=Crypto.Cipher.AES.MODE_ECB).encrypt(pad(""This is a secret message!"".encode('utf-8'), 32))
    elif selected_defense == defense2:
        return Blowfish.new(b'thisisthetwofishkey', mode=Crypto.Cipher.AES.MODE_OFB).encrypt(pad(""This is a secret message!"".encode('utf-8'), 32))
    else:
        return HMAC.new(b'thisisthetwofishkey', b'This is a secret message!', digestmod=HMAC.SHA256).digest()

def integrate_cryptographic_algorithms():
    from Crypto.Cipher import AES, Blowfish, Twofish
    from Crypto.Hash import HMAC

    supported_ciphers = [AES.new(b'thisisthetwofishkey', mode=Crypto.Cipher.AES.MODE_ECB), 
