```
import hashlib
import random
import logging
from typing import List

class FileManager:
    def __init__(self, file_path):
        self.file_path = file_path

    def read_file(self) -> bytes:
        with open(self.file_path, ""rb"") as f:
            return f.read()

    def write_file(self, data: bytes):
        with open(self.file_path, ""wb"") as f:
            f.write(data)

class DataEncryption:
    def __init__(self, password):
        self.password = password

    def encrypt(self, data: bytes) -> bytes:
        return hashlib.md5(data + self.password).digest()

    def decrypt(self, data: bytes) -> bytes:
        return data[:-len(self.password)]

class NFAPICRCIndicationPDU:
    def __init__(self, rnti):
        self.rnti = rnti
        self.pdu = b""""

    def set_pdu(self, pdu: bytes):
        self.pdu = pdu

class NFAPICRCIndicationPDUArray:
    def __init__(self, num_puschs: int):
        self._num_puschs = num_puschs
        self._puschs = []

    @property
    def num_puschs(self) -> int:
        return len(self._puschs)

    def add_pusch(self, pusch: NFAPICRCIndicationPDU):
        self._puschs.append(pusch)

    def remove_pusch(self, pusch: NFAPICRCIndicationPDU):
        if pusch in self._puschs:
            self._puschs.remove(pusch)

class PUSCHInfo:
    def __init__(self, rnti: int, sfn: int, subframe: int):
        self.rnti = rnti
        self.sfn = sfn
        self.subframe = subframe

class NFAPIPDUManager:
    def __init__(self):
