import os
import socket
import hashlib
import base64
import random
from Cryptodome.Cipher import AES
from Cryptodome.Protocol.KDF import Scrypt

class GameNetwork:
    def __init__(self, server_socket):
        self.server_socket = server_socket

    def key_derivation(self, password):
        salt = b'Saltysalt'
        n = 2**14
        r = 8
        p = 1
        dk = Scrypt(password, salt, n, r, p).read()
        return dk

    def initialize_aes_cipher(self):
        iv = bytes([random.getrandbits(8) for _ in range(16)])
        key = self.key_derivation(""password"")
        cipher = AES.new(key, AES.MODE_CBC, iv)
        return cipher

class EventSystem:
    def __init__(self):
        self.events = {}

    def register_event(self, event_name, callback):
        if event_name not in self.events:
            self.events[event_name] = []
        self.events[event_name].append(callback)

    def trigger_event(self, event_name, *args):
        for callback in self.events[event_name]:
            callback(*args)

class Player:
    def __init__(self, name):
        self.name = name

class GameServer:
    def __init__(self, server_socket):
        self.server_socket = server_socket
        self.network = GameNetwork(server_socket)
        self.events = EventSystem()

    def accept_connection(self):
        client_socket, address = self.server_socket.accept()
        print(f""Connection from {address} accepted."")
        return client_socket

    def initialize_game_session(self, client_socket):
        player = Player(""Player 1"")
        print(f""New game session with {player.name}."")
        self.events.trigger_event(""new_game_session"", player)

    def manage_connections(self):
        while True:
            client_socket = self.accept_connection()
            self.initialize_game_session(client_socket)

class GameClient:
    def __init__(self, server_socket):
        self.server_socket = server_socket
        self.network = GameNetwork(server_socket)
        self.events = EventSystem()

    def connect_to_game_server(self):
        client_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        client_socket.connect((self.server_socket.getsockname(), self.server_socket.getsockport()))
        return client_socket

    def send_message(self, message):
        cipher = self.network.initialize_aes_cipher()
        encrypted_message = cipher.encrypt(message)
        self.server_socket.send(encrypted_message)

    def receive_message(self):
        cipher = self.network.initialize_aes_cipher()
        received_message = self.server_socket.recv(1024)
        decrypted_message = cipher.decrypt(received_message)
        return decrypted_message

if __name__ == ""__main__"":
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as server_socket:
        server_socket.bind((socket.gethostname(), 5000))
        server_socket.listen()

        game_server = GameServer(server_socket)
        game_client = GameClient(server_socket)

        client_socket = game_client.connect_to_game_server()
        game_server.manage_connections()
