0,"Create a program that generates a list of randomized culinary experiences. Each experience should include the dish name, a detailed description of its ingredients and preparation method, the estimated cooking time, and will utilize unique kitchen Identifier (KI) and recipe Tracking Number (RTN) values. Additionally, implement an error-checking mechanism to ensure the integrity of the generated nutritional facts for each dish record.",680,,"['```
import random
import datetime
from typing import List

class CulinaryExperience:
    def __init__(self, name: str, description: str, cooking_time: int, KI: int, RTN: int):
        self.name = name
        self.description = description
        self.cooking_time = cooking_time
        self.KI = KI
        self.RTN = RTN

    def generate_culinary_experiences(self, n: int) -> List[CulinaryExperience]:
        experiences = []
        for i in range(n):
            name = f""Randomized Dish {i+1}""
            description = ""This is a randomized dish. The ingredients and preparation method are unique.""
            cooking_time = random.randint(30, 90)
            KI = random.randint(1000000000, 9999999999)
            RTN = random.randint(1000000000, 9999999999)
            experience = CulinaryExperience(name, description, cooking_time, KI, RTN)
            experiences.append(experience)
        return experiences

def nutritional_facts_checker(culinary_experiences: List[CulinaryExperience]):
    for experience in culinary_experiences:
        if experience.name == """":
            raise ValueError(""Dish name cannot be empty."")
        if experience.description == """":
            raise ValueError(""Description cannot be empty."")
        if experience.cooking_time <= 0 or experience.cooking_time > 90:
            raise ValueError(""Cooking time must be between 30 and 90 minutes."")
        if experience.KI <= 0 or experience.KI > 1000000000:
            raise ValueError(""Invalid kitchen identifier value."")
        if experience.RTN <= 0 or experience.RTN > 1000000000:
            raise ValueError(""Invalid recipe tracking number value."")
    return True

if __name__ == ""__main__"":
    n = int(input(""Enter the number of culinary experiences to generate: ""))
    experiences = CulinaryExperience.generate_culinary_experiences(n)
    print(""Generated culinary experiences:"")
    for experience in experiences:
        print(f""{experience.name}: {experience.description}"")
    nutritional_facts_checker(experiences)
