0,"Design and implement a secure file transfer system that utilizes advanced encryption techniques, efficient memory management, and robust error handling. The system should include functions for calculating the SHA-256 hash of a file, encrypting the file using AES-GCM with a randomly generated key and IV, generating an MD5 fingerprint of the encrypted file for integrity verification, and retrieving the server's IP address using DNS resolution. Additionally, the system should incorporate enhanced logging capabilities to track all operations and exceptions during the transfer process. Ensure that the encryption key is securely stored in a configuration file or database to maintain compatibility across different systems. Furthermore, implement a function to check for valid SHA-256 hashes and ensure that only files with valid hashes are transferred. Finally, optimize memory usage by employing efficient data structures for storing transferred files' metadata and implementing parallel processing techniques for faster data transfer over networks with high latency or low bandwidth.",590,,"[""
import hashlib
import os
import socket
from Crypto.Cipher import AES
from Crypto.Protocol.KDF import PBKDF2
from Crypto.Random import get_random_bytes
from Crypto.Util.Padding import pad, unpad
from datetime import datetime
from enum import Enum
import logging

class FileTransferMode(Enum):
    UPLOAD = 1
    DOWNLOAD = 2

class SecureFileTransferSystem:
    def __init__(self, mode=FileTransferMode.UPLOAD):
        self.mode = mode
        self.encryption_key = None
        self.iv = None
        self.logger = logging.getLogger('SecureFileTransferSystem')

    def set_encryption_key(self, key):
        self.encryption_key = key

    def generate_iv(self):
        return get_random_bytes(16)

    def encrypt_file(self, filepath, iv=None):
        if iv is None:
            iv = self.generate_iv()
        with open(filepath, 'rb') as f:
            ciphertext = AES.new(self.encryption_key, AES.MODE_GCM, nonce=iv).encrypt(pad(f.read(), 16))
        return iv + ciphertext

    def decrypt_file(self, filepath):
        with open(filepath, 'rb') as f:
            iv = f.read(16)
            ciphertext = f.read()
            plaintext = AES.new(self.encryption_key, AES.MODE_GCM, nonce=iv).decrypt(ciphertext)
        return unpad(plaintext, 16)

    def calculate_hash(self, filepath):
        with open(filepath, 'rb') as f:
            hash = hashlib.sha256()
            while True:
                chunk = f.read(4096)
                if not chunk:
                    break
                hash.update(chunk)
            return hash.hexdigest()

    def verify_hash(self, filepath):
        expected_hash = self.calculate_hash(filepath)
        actual_hash = self.get_hash_from_metadata(filepath)
        if not expected_hash == actual_hash:
            return False
        else:
            return True

    def get_hash_from_metadata(self, filepath):
        with open(filepath, 'rb') as f:
            iv = f.read(16)
            ciphertext = f.read()
